	/**
	 * A rewrite elsewhere in the query (here the unused-OPTIONAL removal under COUNT(DISTINCT)) builds a copy of the
	 * MINUS over the same body in another group. The original MINUS stays reachable from the root, but its body is this
	 * same MINUS body, not a use of the body's names elsewhere in the query: every copy must keep the anti-join
	 * (MEDICAL q9 selects the copy).
	 */
	@Test
	void rewrittenCopyOfTheMinusKeepsTheCorrelatedAntiJoin() {
		String query = "SELECT (COUNT(DISTINCT ?x) AS ?c) WHERE { VALUES ?x { :a :b } ?x :p ?n "
				+ "OPTIONAL { ?x :h ?w } MINUS { ?x :q ?m . ?m :v ?k } }";
		PackedQuery packed = PackedQueryCodec.encodeForPlanning(parse(query));
		TreeSet<Integer> differenceGroups = new TreeSet<>();
		TreeSet<Integer> antiJoinGroups = new TreeSet<>();
		for (int relationId = 1; relationId <= packed.relationCount(); relationId++) {
			if (packed.relOperator(relationId) == PackedRelOp.DIFFERENCE) {
				differenceGroups.add(packed.relGroup(relationId));
			}
			if ((packed.relRuleMask(relationId) & PackedRuleProofs.MINUS_CORRELATED_NOT_EXISTS) != 0L) {
				antiJoinGroups.add(packed.relGroup(relationId));
			}
		}
		assertTrue(differenceGroups.size() >= 2,
				"precondition: the unused-OPTIONAL removal copies the MINUS into another group: " + differenceGroups);
		assertEquals(differenceGroups, antiJoinGroups,
				"every copy of the MINUS over the same body must offer the correlated anti-join");

		Model data = model();
		add(data, "a", "p", VF.createLiteral(1));
		add(data, "b", "p", VF.createLiteral(2));
		add(data, "a", "q", iri("m1"));
		add(data, "m1", "v", VF.createLiteral(3));
		assertPackedPlanPreservesResults(data, query, ANTI_JOIN_FORCING_COSTS, null,
				List.of("c=\"1\"^^<http://www.w3.org/2001/XMLSchema#integer>"));
	}

